// main.go
package main

import (
    "bufio"
    "fmt"
    "io"
    "net"
    "time"
)

const (
    ChunkSize    = 4096
    MaxChunkSize = 64 * 1024
    ReadTimeout  = 30 * time.Second
)

func main() {
    listener, err := net.Listen("tcp", ":8080")
    if err != nil {
        panic(err)
    }
    defer listener.Close()

    conn, err := listener.Accept()
    if err != nil {
        panic(err)
    }
    defer conn.Close()

    reader := bufio.NewReaderSize(conn, MaxChunkSize)
    schema := []string{"id", "name", "value"}

    stream, err := StartCSVStream(schema)
    if err != nil {
        panic(err)
    }

    buffer := make([]byte, ChunkSize)
    for {
        conn.SetReadDeadline(time.Now().Add(ReadTimeout))
        n, err := reader.Read(buffer)
        if err == io.EOF {
            break
        }
        if err != nil {
            panic(err)
        }

        isLast := n < ChunkSize
        result, err := FeedChunk(stream, buffer[:n], isLast)
        if err != nil {
            panic(err)
        }

        fmt.Println(result)

        if isLast {
            break
        }
    }
}

